const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const victoria = ee.Geometry.Point([-97.0031, 28.8053]);
    const corpusChristi = ee.Geometry.Point([-97.3964, 27.8006]);
    const aoi = victoria.buffer(10000).union(corpusChristi.buffer(10000)); // 10km buffer and union
    const startDate = '2018-06-15';
    const endDate = '2018-06-23'; // Exclusive end date

    // 2. Data Acquisition & Check
    const dataset = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
        .filterDate(startDate, endDate)
        .filterBounds(aoi);

    const imageCount = dataset.size().getInfo();
    if (imageCount === 0) {
        console.log("No GPM images found for the specified date and location.");
        console.log("A: No");
        return;
    }
    console.log(`Found ${imageCount} GPM images (half-hourly intervals).`);

    // 3. Processing
    // GPM precipitationCal is in mm/hr. Each image is a 30-minute observation.
    // Sum all observations and multiply by 0.5 hr/observation to get total mm.
    const totalPrecipitationMm = dataset.select('precipitationCal').sum().multiply(0.5);

    // 4. Calculation
    const stats = totalPrecipitationMm.reduceRegion({
        reducer: ee.Reducer.mean().setOutputs(['precip']).combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }).setOutputs(['precip', 'count']),
        geometry: aoi,
        scale: 10000,
        maxPixels: 1e9
    });

    const precipMm = stats.get('precip').getInfo();
    const pixelCount = stats.get('count').getInfo();

    // 5. Validation & Final Answer
    if (pixelCount === 0) {
        console.log("No valid pixels found in the area of interest.");
        console.log("C2: No Valid Pixels");
        return;
    }

    if (precipMm === null || typeof precipMm === 'undefined') {
        console.log("Calculation failed: could not retrieve precipitation value.");
        console.log("C3: Calculation Failure");
        return;
    }

    // Convert total millimeters to inches (1 inch = 25.4 mm)
    const precipInches = precipMm / 25.4;

    console.log(`Average Total Precipitation (mm): ${precipMm.toFixed(2)}`);
    console.log(`Average Total Precipitation (inches): ${precipInches.toFixed(2)}`);
    console.log(`Valid Pixels Counted: ${pixelCount}`);

    if (precipInches < 20) {
        console.log("A: Yes");
    } else {
        console.log("B: No");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error("An error occurred during initialization or analysis:", e);
        console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
    }
}

initEE();
